sys_ui_action.script:
current.setValue("states","3"); 
current.update(); 


var grMedia = new GlideRecord("x_357506_netflix_media");
grMedia.addEncodedQuery("title=" + current.getValue("title") +  "^type=" + current.getValue("type") +  "^release_year=" + current.getValue("release_year") +  "^sys_id!=" + current.getValue("sys_id"));
grMedia.query();

while (grMedia.next()){
	grMedia.setValue("states","7");
	grMedia.setValue("genre","");
	grMedia.setValue("release_date","");
	grMedia.setValue("release_year","");
	grMedia.setValue("category","");
	grMedia.setValue("synopsis","");
	grMedia.setValue("writters","");
	grMedia.setValue("production","");
	grMedia.setValue("poster","");
	grMedia.setValue("website","");
	grMedia.setValue("average_grade","");
	grMedia.setValue("imdb_rating","");
	grMedia.setValue("metascore","");
	grMedia.setValue("awards","");
	grMedia.setValue("language","");
	grMedia.setValue("country","");
	grMedia.setValue("integration_state","3");
	grMedia.setValue("integration_error_message","");

var grDirectors = new GlideRecord("x_357506_netflix_m2m_directors_medias");
grDirectors.addEncodedQuery("x_357506_netflix_media=" +grMedia.getValue("sys_id"));
grDirectors.query();
grDirectors.deleteMultiple();

var grActors = new GlideRecord("x_357506_netflix_m2m_actors_medias");
grActors.addEncodedQuery("x_357506_netflix_media=" +grMedia.getValue("sys_id"));
grActors.query();
grActors.deleteMultiple();
grMedia.update();

}


action.setRedirectURL(current); // vai permanecer na página
